#!/usr/bin/env python3
"""Materialize project config and skills without overwriting existing content."""
import argparse
import json
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]


def planned_files(root, preset=None):
    models = json.loads((root / "harness/models.json").read_text())
    selected = models["presets"][preset or models["default"]]
    config = (
        '# Generated by scripts/activate.py; model source: harness/models.json\n'
        f'model = {json.dumps(selected["model"])}\n'
        f'model_reasoning_effort = {json.dumps(selected["effort"])}\n'
    ).encode()
    files = {Path(".codex/config.toml"): config}
    for skill in sorted((root / "harness/skills").glob("*/SKILL.md")):
        files[Path(".agents/skills") / skill.parent.name / "SKILL.md"] = skill.read_bytes()
    return files


def activate(root, preset=None, dry_run=False):
    files = planned_files(root, preset)
    # Preflight every destination before making any writes.
    for rel, content in files.items():
        dest = root / rel
        for part in (dest, *dest.parents):
            if part == root:
                break
            if part.is_symlink():
                raise ValueError(f"Refusing symlink destination: {part}")
            if part != dest and part.exists() and not part.is_dir():
                raise ValueError(f"Destination parent is not a directory: {part}")
        if dest.exists() and (not dest.is_file() or dest.read_bytes() != content):
            raise ValueError(f"Existing file differs; merge manually: {dest}")
    for rel, content in files.items():
        dest = root / rel
        if dest.exists():
            print(f"unchanged: {rel}")
        elif dry_run:
            print(f"would create: {rel}")
        else:
            dest.parent.mkdir(parents=True, exist_ok=True)
            with dest.open("xb") as stream:
                stream.write(content)
            print(f"created: {rel}")


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--preset", choices=["standard", "latest", "light", "fast", "deep"])
    parser.add_argument("--dry-run", action="store_true")
    args = parser.parse_args()
    try:
        activate(ROOT, args.preset, args.dry_run)
    except (OSError, ValueError, KeyError) as error:
        parser.exit(1, f"Activation stopped: {error}\n")


if __name__ == "__main__":
    main()
